// Conditional formats in the workbook view: what reaches the canvas, and how it
// follows edits, undo and inserted rows.
//
// Pixels are sampled at positions written out by hand from the default sizes
// of a sheet (header 72 x 22, columns 64 wide, rows 20 high). Every workbook
// is generated by code. Everything is kept within columns A to D, so that a
// phone shows it as well.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
const NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const cf = (sqref: string, rules: string) => `<conditionalFormatting sqref="${sqref}">${rules}</conditionalFormatting>`;

/** 0: red fill. 1: yellow fill, bold. 2: blue fill. */
const STYLES =
  `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="${NS}">` +
  '<fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts>' +
  '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>' +
  '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>' +
  '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>' +
  '<cellXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs>' +
  '<dxfs count="3">' +
  // The colour of a differential fill is bgColor; the fgColor here must not show.
  '<dxf><fill><patternFill><fgColor rgb="FF00FF00"/><bgColor rgb="FFFF0000"/></patternFill></fill></dxf>' +
  '<dxf><font><b/></font><fill><patternFill patternType="solid"><bgColor rgb="FFFFFF00"/></patternFill></fill></dxf>' +
  '<dxf><fill><patternFill><bgColor rgb="FF0000FF"/></patternFill></fill></dxf>' +
  '</dxfs></styleSheet>';

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/**
 * A: 1, 5, 9, "x", (empty)   red where the value is above 4
 * B: 0, 25, 50, 75, 100      colour scale from red to blue
 * C: 50, 100                 solid green data bars, limits automatic
 * D: 1, 5, 9                 traffic lights
 * Row 7: A7 = 3              yellow across A7:D7 when $A7 > 5 (a formula)
 */
const rulesWorkbook = once(() =>
  buildXlsx({
    styles: STYLES,
    sheets: [
      {
        name: 'Rules',
        xml: worksheetXml(
          '<sheetData>' +
            `<row r="1">${num('A1', 1)}${num('B1', 0)}${num('C1', 50)}${num('D1', 1)}</row>` +
            `<row r="2">${num('A2', 5)}${num('B2', 25)}${num('C2', 100)}${num('D2', 5)}</row>` +
            `<row r="3">${num('A3', 9)}${num('B3', 50)}${num('D3', 9)}</row>` +
            `<row r="4">${str('A4', 'x')}${num('B4', 75)}</row>` +
            `<row r="5">${num('B5', 100)}</row>` +
            `<row r="7">${num('A7', 3)}</row>` +
            '</sheetData>' +
            cf('A1:A5', '<cfRule type="cellIs" dxfId="0" priority="1" operator="greaterThan"><formula>4</formula></cfRule>') +
            cf('B1:B5', '<cfRule type="colorScale" priority="2"><colorScale><cfvo type="min"/><cfvo type="max"/><color rgb="FFFF0000"/><color rgb="FF0000FF"/></colorScale></cfRule>') +
            cf(
              'C1:C2',
              '<cfRule type="dataBar" priority="3"><dataBar><cfvo type="min"/><cfvo type="max"/><color rgb="FF00B050"/></dataBar>' +
                '<extLst><ext xmlns:x14="http://schemas.microsoft.com/office/spreadsheetml/2009/9/main" uri="{B025F937-C7B1-47D3-B67F-A62EFF666E3E}"><x14:id>{BAR-1}</x14:id></ext></extLst></cfRule>',
            ) +
            cf('D1:D3', '<cfRule type="iconSet" priority="4"><iconSet iconSet="3TrafficLights1"><cfvo type="percent" val="0"/><cfvo type="percent" val="33"/><cfvo type="percent" val="67"/></iconSet></cfRule>') +
            cf('A7:D7', '<cfRule type="expression" dxfId="1" priority="5"><formula>$A7&gt;5</formula></cfRule>') +
            '<extLst><ext xmlns:x14="http://schemas.microsoft.com/office/spreadsheetml/2009/9/main" uri="{78C0D931-6437-407d-A8EE-F0AAD7539E65}">' +
            '<x14:conditionalFormattings><x14:conditionalFormatting xmlns:xm="http://schemas.microsoft.com/office/excel/2006/main">' +
            '<x14:cfRule type="dataBar" id="{BAR-1}"><x14:dataBar minLength="0" maxLength="100" gradient="0"><x14:cfvo type="autoMin"/><x14:cfvo type="autoMax"/></x14:dataBar></x14:cfRule>' +
            '<xm:sqref>C1:C2</xm:sqref></x14:conditionalFormatting></x14:conditionalFormattings></ext></extLst>',
        ),
      },
    ],
  }),
);

/** 2,000 rows under a whole-column rule: blue where the value repeats (every 500th row holds 7, the others their row number). */
const tallWorkbook = once(() => {
  let rows = '';
  for (let r = 1; r <= 2000; r++) rows += `<row r="${r}">${num(`A${r}`, r % 500 === 0 ? 7 : r + 10)}</row>`;
  return buildXlsx({
    styles: STYLES,
    sheets: [{ name: 'Tall', xml: worksheetXml(`<sheetData>${rows}</sheetData>` + cf('A1:A1048576', '<cfRule type="duplicateValues" dxfId="2" priority="1"/>')) }],
  });
});

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

/** Colour of one canvas pixel (CSS coordinates relative to the canvas) after a forced redraw. */
function pixel(page: Page, x: number, y: number): Promise<number[]> {
  return page.evaluate(
    ([x, y]) => {
      const view = (window as any).__view;
      view.render();
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      return Array.from(canvas.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), 1, 1).data).slice(0, 3);
    },
    [x, y],
  );
}

/** A point inside a cell: `fx` and `fy` are fractions of its width and height. The cell's text is right-aligned, so 0.2 across is clear of it. */
const inCell = (col: number, row: number, fx = 0.2, fy = 0.25) => ({ x: HEADER_WIDTH + (col + fx) * COLUMN_WIDTH, y: HEADER_HEIGHT + (row + fy) * ROW_HEIGHT });

const colourAt = (page: Page, col: number, row: number, fx?: number, fy?: number) => {
  const point = inCell(col, row, fx, fy);
  return pixel(page, point.x, point.y);
};

const RED = [255, 0, 0];
const WHITE = [255, 255, 255];
const YELLOW = [255, 255, 0];
const BLUE = [0, 0, 255];
const BAR_GREEN = [0, 176, 80];

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', `return ${code}`)((window as any).__view), code);

test.describe('conditional formats', () => {
  test('fills, a colour scale, data bars and icons are drawn', async ({ page }) => {
    await mount(page, await rulesWorkbook());

    // A: above 4 is red; the text "x" ranks above every number and is red as well; 1 and the empty cell are not.
    expect(await colourAt(page, 0, 0)).toEqual(WHITE);
    expect(await colourAt(page, 0, 1)).toEqual(RED);
    expect(await colourAt(page, 0, 2)).toEqual(RED);
    expect(await colourAt(page, 0, 3, 0.8)).toEqual(RED);
    expect(await colourAt(page, 0, 4)).toEqual(WHITE);

    // B: red at the minimum, blue at the maximum, the mixture halfway.
    expect(await colourAt(page, 1, 0)).toEqual(RED);
    expect(await colourAt(page, 1, 2)).toEqual([128, 0, 128]);
    expect(await colourAt(page, 1, 4)).toEqual(BLUE);
    expect(await colourAt(page, 1, 5)).toEqual(WHITE);

    // C: 50 of 100 fills the left half of its cell, 100 all of it. Sampled above the text.
    expect(await colourAt(page, 2, 0, 0.25)).toEqual(BAR_GREEN);
    expect(await colourAt(page, 2, 0, 0.7)).toEqual(WHITE);
    expect(await colourAt(page, 2, 1, 0.25)).toEqual(BAR_GREEN);
    expect(await colourAt(page, 2, 1, 0.7)).toEqual(BAR_GREEN);
    expect(await colourAt(page, 2, 2, 0.25)).toEqual(WHITE);

    // D: a circle of 15 px at the left of the cell, its centre 10.5 px below the top of the row.
    const icon = (row: number) => pixel(page, HEADER_WIDTH + 3 * COLUMN_WIDTH + 3 + 7.5, HEADER_HEIGHT + row * ROW_HEIGHT + 10.5);
    const [low, middle, high] = [await icon(0), await icon(1), await icon(2)];
    // Red, yellow and green lights: red has little green, green has less red than green, yellow has much of both.
    expect(low[0]).toBeGreaterThan(180);
    expect(low[1]).toBeLessThan(120);
    expect(middle[0]).toBeGreaterThan(200);
    expect(middle[1]).toBeGreaterThan(160);
    expect(high[1]).toBeGreaterThan(high[0] + 30);
    // No icon in a cell outside the rule.
    expect(await icon(3)).toEqual(WHITE);

    // Row 7: 3 is not above 5.
    expect(await colourAt(page, 1, 6)).toEqual(WHITE);
  });

  test('a rule with a formula applies on the first drawing, also in a read-only view; not without calculation', async ({ page }) => {
    const bytes = await buildXlsx({
      styles: STYLES,
      sheets: [
        {
          name: 'Formula',
          xml: worksheetXml(
            `<sheetData><row r="1">${num('A1', 9)}${num('B1', 1)}</row><row r="2">${num('A2', 2)}${num('B2', 1)}</row></sheetData>` +
              cf('A1:C2', '<cfRule type="expression" dxfId="1" priority="1"><formula>$A1&gt;SUM($B$1:$B$2)*3</formula></cfRule>') +
              cf('A1:A2', '<cfRule type="cellIs" dxfId="0" priority="2" operator="lessThan"><formula>5</formula></cfRule>'),
          ),
        },
      ],
    });
    for (const options of [{}, { readOnly: true }]) {
      await mount(page, bytes, options);
      // 9 > 6: all of row 1 within the range, the empty C1 included; row 2 only gets the red of "less than 5".
      expect(await colourAt(page, 0, 0)).toEqual(YELLOW);
      expect(await colourAt(page, 2, 0)).toEqual(YELLOW);
      expect(await colourAt(page, 3, 0)).toEqual(WHITE);
      expect(await colourAt(page, 0, 1)).toEqual(RED);
      expect(await colourAt(page, 1, 1)).toEqual(WHITE);
    }
    await mount(page, bytes, { calculate: false });
    // Formulas are off; the rule with a plain number still works.
    expect(await colourAt(page, 0, 0)).toEqual(WHITE);
    expect(await colourAt(page, 0, 1)).toEqual(RED);
  });

  test('the formats follow an edit and come back with undo', async ({ page }) => {
    await mount(page, await rulesWorkbook());

    // A1: 1 -> 9 turns red.
    expect(await colourAt(page, 0, 0)).toEqual(WHITE);
    await view(page, "view.setCellInput(0, 0, '9')");
    expect(await colourAt(page, 0, 0)).toEqual(RED);

    // B5: 100 -> 300 moves the top of the scale; 50 is a sixth of the way now, not half.
    await view(page, "view.setCellInput(4, 1, '300')");
    expect(await colourAt(page, 1, 2)).toEqual([213, 0, 43]);
    expect(await colourAt(page, 1, 4)).toEqual(BLUE);

    // C2: 100 -> 25 makes 50 the longest bar.
    await view(page, "view.setCellInput(1, 2, '25')");
    expect(await colourAt(page, 2, 0, 0.7)).toEqual(BAR_GREEN);
    expect(await colourAt(page, 2, 1, 0.7)).toEqual(WHITE);
    expect(await colourAt(page, 2, 1, 0.25)).toEqual(BAR_GREEN);

    // A7: 3 -> 8 satisfies the formula for the whole row of the range.
    await view(page, "view.setCellInput(6, 0, '8')");
    expect(await colourAt(page, 0, 6)).toEqual(YELLOW);
    expect(await colourAt(page, 3, 6)).toEqual(YELLOW);

    // Undo, one step at a time, in reverse.
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await colourAt(page, 3, 6)).toEqual(WHITE);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await colourAt(page, 2, 0, 0.7)).toEqual(WHITE);
    expect(await colourAt(page, 2, 1, 0.7)).toEqual(BAR_GREEN);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await colourAt(page, 1, 2)).toEqual([128, 0, 128]);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await colourAt(page, 0, 0)).toEqual(WHITE);

    // And redo brings the first edit back.
    expect(await view(page, 'view.redo()')).toBe(true);
    expect(await colourAt(page, 0, 0)).toEqual(RED);
  });

  test('the formats move with rows inserted above them', async ({ page }) => {
    await mount(page, await rulesWorkbook());
    expect(await colourAt(page, 0, 1)).toEqual(RED);
    await view(page, 'view.insertRows(0, 1)');
    // Everything is one row lower: the 5 of A2 is in A3 and red, A2 holds the 1 and is not.
    expect(await colourAt(page, 0, 1)).toEqual(WHITE);
    expect(await colourAt(page, 0, 2)).toEqual(RED);
    expect(await colourAt(page, 1, 1)).toEqual(RED);
    expect(await colourAt(page, 1, 5)).toEqual(BLUE);
    expect(await colourAt(page, 2, 1, 0.25)).toEqual(BAR_GREEN);
    // The formula of row 7 follows to row 8.
    await view(page, "view.setCellInput(7, 0, '8')");
    expect(await colourAt(page, 3, 7)).toEqual(YELLOW);
    expect(await colourAt(page, 3, 6)).toEqual(WHITE);

    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await colourAt(page, 0, 1)).toEqual(RED);
    expect(await colourAt(page, 0, 2)).toEqual(RED);
    expect(await colourAt(page, 1, 0)).toEqual(RED);
  });

  test('a whole-column rule is drawn wherever the view is scrolled to', async ({ page }) => {
    await mount(page, await tallWorkbook());
    expect(await colourAt(page, 0, 0)).toEqual(WHITE);
    /** Colour of column A in a sheet row, wherever that row is on the canvas now. */
    const rowColour = async (row: number) => {
      const scrollY = (await view(page, 'view.getViewState().scrollY')) as number;
      return pixel(page, HEADER_WIDTH + 0.2 * COLUMN_WIDTH, HEADER_HEIGHT + row * ROW_HEIGHT - scrollY + 0.25 * ROW_HEIGHT);
    };
    await view(page, 'view.scrollTo(1499, 0)');
    expect((await view(page, 'view.getViewState().scrollY')) as number).toBeGreaterThan(1400 * ROW_HEIGHT);
    // Row 1500 holds one of the repeated values; the row above it does not.
    expect(await rowColour(1499)).toEqual(BLUE);
    expect(await rowColour(1498)).toEqual(WHITE);
    // One of the four is changed: the other three still repeat.
    await view(page, "view.setCellInput(1499, 0, '1')");
    expect(await rowColour(1499)).toEqual(WHITE);
    await view(page, 'view.scrollTo(999, 0)');
    expect(await rowColour(999)).toEqual(BLUE);
    expect(await view(page, 'view.undo()')).toBe(true);
    await view(page, 'view.scrollTo(1499, 0)');
    expect(await rowColour(1499)).toEqual(BLUE);
  });
});
